package com.github.outlashed.granitetracker;

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Component;
import java.awt.Cursor;
import java.awt.Dimension;
import java.awt.GridLayout;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import javax.inject.Inject;
import javax.inject.Singleton;
import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.DefaultListCellRenderer;
import javax.swing.JButton;
import javax.swing.JComboBox;
import javax.swing.JLabel;
import javax.swing.JList;
import javax.swing.JPanel;
import javax.swing.JTextField;
import javax.swing.border.CompoundBorder;
import javax.swing.border.EmptyBorder;
import javax.swing.border.MatteBorder;
import net.runelite.client.config.ConfigManager;
import com.github.outlashed.granitetracker.model.ProfileData;
import com.github.outlashed.granitetracker.services.GraniteTrackingService;
import com.github.outlashed.granitetracker.services.ProfileStorageService;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.PluginPanel;

@Singleton
public class GraniteTrackerPanel extends PluginPanel
{
    private static final Color COLOR_DANGER  = new Color(0xC0, 0x39, 0x2B);
    private static final Color COLOR_SUCCESS = new Color(0x27, 0x7A, 0x50);
    private static final Color COLOR_INACTIVE = ColorScheme.MEDIUM_GRAY_COLOR;

    private final GraniteTrackingService graniteTrackingService;
    private final ProfileStorageService profileStorageService;
    private final ConfigManager configManager;
    private final GraniteTrackerConfig config;

    private final JTextField profileNameField = new JTextField();
    private final JComboBox<String> profileDropdown = new JComboBox<>();

    private JButton generalStatsToggle;
    private JButton graniteOverlayToggle;

    @Inject
    public GraniteTrackerPanel(GraniteTrackingService graniteTrackingService,
                               ProfileStorageService profileStorageService,
                               ConfigManager configManager,
                               GraniteTrackerConfig config)
    {
        this.graniteTrackingService = graniteTrackingService;
        this.profileStorageService = profileStorageService;
        this.configManager = configManager;
        this.config = config;
        buildUI();
    }

    private void buildUI()
    {
        setLayout(new BoxLayout(this, BoxLayout.Y_AXIS));
        setBorder(new EmptyBorder(0, 0, 0, 0));

        add(buildTitleBar());
        add(buildSaveSection());
        add(buildLoadSection());
        add(buildOverlaySection());
        add(buildResetSection());
    }

    // ── Title ────────────────────────────────────────────────────────────────

    private JPanel buildTitleBar()
    {
        JPanel panel = new JPanel(new BorderLayout());
        panel.setBackground(ColorScheme.DARKER_GRAY_COLOR);
        panel.setBorder(new CompoundBorder(
                new MatteBorder(0, 0, 1, 0, ColorScheme.BRAND_ORANGE.darker()),
                new EmptyBorder(10, 12, 10, 12)
        ));
        panel.setMaximumSize(new Dimension(Integer.MAX_VALUE, 44));

        JLabel title = new JLabel("Granite Tracker");
        title.setForeground(Color.WHITE);
        title.setFont(FontManager.getRunescapeFont());
        panel.add(title, BorderLayout.WEST);

        return panel;
    }

    // ── Save profile ─────────────────────────────────────────────────────────

    private JPanel buildSaveSection()
    {
        JPanel panel = new JPanel();
        panel.setLayout(new BoxLayout(panel, BoxLayout.Y_AXIS));
        panel.setBackground(ColorScheme.DARK_GRAY_COLOR);
        panel.setBorder(new CompoundBorder(
                new MatteBorder(1, 0, 0, 0, ColorScheme.DARKER_GRAY_COLOR),
                new EmptyBorder(10, 10, 10, 10)
        ));
        panel.setMaximumSize(new Dimension(Integer.MAX_VALUE, Integer.MAX_VALUE));

        panel.add(buildSectionLabel("PROFILES"));
        panel.add(Box.createRigidArea(new Dimension(0, 8)));

        JLabel nameLabel = new JLabel("Profile name");
        nameLabel.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
        nameLabel.setFont(FontManager.getRunescapeFont());
        nameLabel.setHorizontalAlignment(JLabel.LEFT);
        nameLabel.setAlignmentX(Component.CENTER_ALIGNMENT);
        nameLabel.setMaximumSize(new Dimension(Integer.MAX_VALUE, 20));
        panel.add(nameLabel);
        panel.add(Box.createRigidArea(new Dimension(0, 8)));

        styleTextField(profileNameField);
        panel.add(profileNameField);
        panel.add(Box.createRigidArea(new Dimension(0, 8)));

        JButton saveButton = buildButton("Save Current Session", COLOR_SUCCESS);
        saveButton.addActionListener(e -> saveProfile());
        panel.add(saveButton);

        return panel;
    }

    // ── Load / Delete profile ────────────────────────────────────────────────

    private JPanel buildLoadSection()
    {
        JPanel panel = new JPanel();
        panel.setLayout(new BoxLayout(panel, BoxLayout.Y_AXIS));
        panel.setBackground(ColorScheme.DARK_GRAY_COLOR);
        panel.setBorder(new CompoundBorder(
                new MatteBorder(1, 0, 0, 0, ColorScheme.DARKER_GRAY_COLOR),
                new EmptyBorder(10, 10, 10, 10)
        ));
        panel.setMaximumSize(new Dimension(Integer.MAX_VALUE, Integer.MAX_VALUE));

        panel.add(buildSectionLabel("SAVED PROFILES"));
        panel.add(Box.createRigidArea(new Dimension(0, 8)));

        styleComboBox(profileDropdown);
        refreshProfileDropdown();
        panel.add(profileDropdown);
        panel.add(Box.createRigidArea(new Dimension(0, 8)));

        JButton loadButton   = buildButton("Load",   COLOR_SUCCESS);
        JButton deleteButton = buildButton("Delete", COLOR_DANGER);
        loadButton.addActionListener(e -> loadProfile());
        deleteButton.addActionListener(e -> deleteProfile());

        JPanel buttons = new JPanel(new GridLayout(1, 2, 6, 0));
        buttons.setBackground(ColorScheme.DARK_GRAY_COLOR);
        buttons.setAlignmentX(Component.CENTER_ALIGNMENT);
        buttons.setMaximumSize(new Dimension(Integer.MAX_VALUE, 32));
        buttons.add(loadButton);
        buttons.add(deleteButton);
        panel.add(buttons);

        return panel;
    }

    // ── Overlay toggles ──────────────────────────────────────────────────────

    private JPanel buildOverlaySection()
    {
        JPanel panel = new JPanel();
        panel.setLayout(new BoxLayout(panel, BoxLayout.Y_AXIS));
        panel.setBackground(ColorScheme.DARK_GRAY_COLOR);
        panel.setBorder(new CompoundBorder(
                new MatteBorder(1, 0, 0, 0, ColorScheme.DARKER_GRAY_COLOR),
                new EmptyBorder(10, 10, 10, 10)
        ));
        panel.setMaximumSize(new Dimension(Integer.MAX_VALUE, Integer.MAX_VALUE));

        panel.add(buildSectionLabel("OVERLAYS"));
        panel.add(Box.createRigidArea(new Dimension(0, 8)));

        generalStatsToggle = buildToggleButton("General Statistics", config.showGeneralStats());
        generalStatsToggle.addActionListener(e ->
        {
            boolean newVal = !config.showGeneralStats();
            configManager.setConfiguration("granitetracker", "showGeneralStats", newVal);
            applyToggleColor(generalStatsToggle, newVal);
        });
        panel.add(generalStatsToggle);
        panel.add(Box.createRigidArea(new Dimension(0, 6)));

        graniteOverlayToggle = buildToggleButton("Granite Distribution", config.showGraniteOverlay());
        graniteOverlayToggle.addActionListener(e ->
        {
            boolean newVal = !config.showGraniteOverlay();
            configManager.setConfiguration("granitetracker", "showGraniteOverlay", newVal);
            applyToggleColor(graniteOverlayToggle, newVal);
        });
        panel.add(graniteOverlayToggle);

        return panel;
    }

    // ── Reset ────────────────────────────────────────────────────────────────

    private JPanel buildResetSection()
    {
        JPanel panel = new JPanel();
        panel.setLayout(new BoxLayout(panel, BoxLayout.Y_AXIS));
        panel.setBackground(ColorScheme.DARK_GRAY_COLOR);
        panel.setBorder(new CompoundBorder(
                new MatteBorder(1, 0, 0, 0, ColorScheme.DARKER_GRAY_COLOR),
                new EmptyBorder(10, 10, 10, 10)
        ));
        panel.setMaximumSize(new Dimension(Integer.MAX_VALUE, Integer.MAX_VALUE));

        JButton resetButton = buildButton("Reset Statistics", COLOR_DANGER);
        resetButton.addActionListener(e -> graniteTrackingService.reset());
        panel.add(resetButton);

        return panel;
    }

    // ── Helpers ──────────────────────────────────────────────────────────────

    private JLabel buildSectionLabel(String text)
    {
        JLabel label = new JLabel(text, JLabel.CENTER);
        label.setForeground(ColorScheme.BRAND_ORANGE);
        label.setFont(FontManager.getRunescapeSmallFont());
        label.setAlignmentX(Component.CENTER_ALIGNMENT);
        label.setMaximumSize(new Dimension(Integer.MAX_VALUE, 16));
        return label;
    }

    private JButton buildButton(String text, Color baseColor)
    {
        Color hoverColor = baseColor.brighter();
        Color pressColor = baseColor.darker();

        JButton button = new JButton(text);
        button.setBackground(baseColor);
        button.setForeground(Color.WHITE);
        button.setFont(FontManager.getRunescapeFont());
        button.setFocusPainted(false);
        button.setBorderPainted(false);
        button.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
        button.setAlignmentX(Component.CENTER_ALIGNMENT);
        button.setMaximumSize(new Dimension(Integer.MAX_VALUE, 32));

        button.addMouseListener(new MouseAdapter()
        {
            @Override public void mouseEntered(MouseEvent e)  { button.setBackground(hoverColor); }
            @Override public void mouseExited(MouseEvent e)   { button.setBackground(baseColor);  }
            @Override public void mousePressed(MouseEvent e)  { button.setBackground(pressColor); }
            @Override public void mouseReleased(MouseEvent e) { button.setBackground(hoverColor); }
        });

        return button;
    }

    private void styleTextField(JTextField field)
    {
        field.setBackground(ColorScheme.DARKER_GRAY_COLOR);
        field.setForeground(Color.WHITE);
        field.setCaretColor(Color.WHITE);
        field.setFont(FontManager.getRunescapeFont());
        field.setBorder(new CompoundBorder(
                new MatteBorder(0, 0, 1, 0, ColorScheme.BRAND_ORANGE.darker()),
                new EmptyBorder(4, 6, 4, 6)
        ));
        field.setAlignmentX(Component.CENTER_ALIGNMENT);
        field.setMaximumSize(new Dimension(Integer.MAX_VALUE, 32));
    }

    private void styleComboBox(JComboBox<String> combo)
    {
        combo.setBackground(ColorScheme.DARKER_GRAY_COLOR);
        combo.setForeground(Color.WHITE);
        combo.setFont(FontManager.getRunescapeFont());
        combo.setBorder(new MatteBorder(0, 0, 1, 0, ColorScheme.BRAND_ORANGE.darker()));
        combo.setAlignmentX(Component.CENTER_ALIGNMENT);
        combo.setMaximumSize(new Dimension(Integer.MAX_VALUE, 32));
        combo.setRenderer(new DefaultListCellRenderer()
        {
            @Override
            public Component getListCellRendererComponent(JList<?> list, Object value,
                    int index, boolean isSelected, boolean cellHasFocus)
            {
                super.getListCellRendererComponent(list, value, index, isSelected, cellHasFocus);
                setBackground(isSelected
                        ? ColorScheme.BRAND_ORANGE.darker()
                        : ColorScheme.DARKER_GRAY_COLOR);
                setForeground(Color.WHITE);
                setFont(FontManager.getRunescapeFont());
                setBorder(new EmptyBorder(4, 6, 4, 6));
                return this;
            }
        });
    }

    private JButton buildToggleButton(String text, boolean active)
    {
        JButton button = new JButton(text);
        button.setForeground(Color.WHITE);
        button.setFont(FontManager.getRunescapeFont());
        button.setFocusPainted(false);
        button.setBorderPainted(false);
        button.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
        button.setAlignmentX(Component.CENTER_ALIGNMENT);
        button.setMaximumSize(new Dimension(Integer.MAX_VALUE, 32));
        applyToggleColor(button, active);
        return button;
    }

    private void applyToggleColor(JButton button, boolean active)
    {
        button.setBackground(active ? COLOR_SUCCESS : COLOR_INACTIVE);
    }

    // ── Actions ──────────────────────────────────────────────────────────────

    private void saveProfile()
    {
        String name = profileNameField.getText().trim();
        if (name.isEmpty())
        {
            return;
        }
        profileStorageService.saveProfile(name, graniteTrackingService);
        refreshProfileDropdown();
        profileNameField.setText("");
    }

    private void loadProfile()
    {
        String name = (String) profileDropdown.getSelectedItem();
        if (name == null)
        {
            return;
        }
        ProfileData data = profileStorageService.loadProfile(name);
        if (data != null)
        {
            graniteTrackingService.loadFromProfile(data);
        }
    }

    private void deleteProfile()
    {
        String name = (String) profileDropdown.getSelectedItem();
        if (name == null)
        {
            return;
        }
        profileStorageService.deleteProfile(name);
        refreshProfileDropdown();
    }

    private void refreshProfileDropdown()
    {
        profileDropdown.removeAllItems();
        for (String name : profileStorageService.getProfileNames())
        {
            profileDropdown.addItem(name);
        }
    }
}

package com.github.outlashed.granitetracker;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

@ConfigGroup("granitetracker")
public interface GraniteTrackerConfig extends Config
{
    @ConfigItem(
            keyName = "showGeneralStats",
            name = "Show General Statistics",
            description = "Toggles the General Statistics overlay"
    )
    default boolean showGeneralStats()
    {
        return true;
    }

    @ConfigItem(
            keyName = "showGraniteOverlay",
            name = "Show Granite Distribution",
            description = "Toggles the Granite Distribution overlay"
    )
    default boolean showGraniteOverlay()
    {
        return true;
    }
}

package com.github.outlashed.granitetracker.model;

public class ProfileData
{
    public String name;
    public int attempts;
    public int successes;
    public int varrockArmorCount;
    public int celestialRingCount;
    public int miningCapeCount;
    public int count500g;
    public int count2kg;
    public int count5kg;
}

package com.github.outlashed.granitetracker.services;

import com.google.gson.Gson;
import com.google.gson.reflect.TypeToken;
import java.lang.reflect.Type;
import java.util.ArrayList;
import java.util.List;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.client.config.ConfigManager;
import com.github.outlashed.granitetracker.model.ProfileData;

@Singleton
public class ProfileStorageService
{
    private static final String CONFIG_GROUP = "granitetracker";
    private static final String PROFILE_NAMES_KEY = "savedProfileNames";
    private static final String PROFILE_PREFIX = "profile.";
    private static final Type STRING_LIST_TYPE = new TypeToken<List<String>>(){}.getType();

    @Inject
    private Gson gson;

    @Inject
    private ConfigManager configManager;

    public void saveProfile(String name, GraniteTrackingService service)
    {
        ProfileData data = new ProfileData();
        data.name = name;
        data.attempts = service.getAttempts();
        data.successes = service.getSuccesses();
        data.varrockArmorCount = service.getVarrockArmorCount();
        data.celestialRingCount = service.getCelestialRingCount();
        data.miningCapeCount = service.getMiningCapeCount();
        data.count500g = service.getCount500g();
        data.count2kg = service.getCount2kg();
        data.count5kg = service.getCount5kg();

        configManager.setConfiguration(CONFIG_GROUP, PROFILE_PREFIX + name, gson.toJson(data));

        List<String> names = getProfileNames();
        if (!names.contains(name))
        {
            names.add(name);
            configManager.setConfiguration(CONFIG_GROUP, PROFILE_NAMES_KEY, gson.toJson(names));
        }
    }

    public ProfileData loadProfile(String name)
    {
        String json = configManager.getConfiguration(CONFIG_GROUP, PROFILE_PREFIX + name);
        if (json == null || json.isEmpty())
        {
            return null;
        }
        return gson.fromJson(json, ProfileData.class);
    }

    public void deleteProfile(String name)
    {
        configManager.unsetConfiguration(CONFIG_GROUP, PROFILE_PREFIX + name);
        List<String> names = getProfileNames();
        names.remove(name);
        configManager.setConfiguration(CONFIG_GROUP, PROFILE_NAMES_KEY, gson.toJson(names));
    }

    public List<String> getProfileNames()
    {
        String json = configManager.getConfiguration(CONFIG_GROUP, PROFILE_NAMES_KEY);
        if (json == null || json.isEmpty())
        {
            return new ArrayList<>();
        }
        List<String> names = gson.fromJson(json, STRING_LIST_TYPE);
        return names != null ? names : new ArrayList<>();
    }
}

package com.github.outlashed.granitetracker.services;

import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.Skill;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.StatChanged;
import net.runelite.api.events.VarbitChanged;
import com.github.outlashed.granitetracker.model.ProfileData;

@Slf4j
@Singleton
public class GraniteTrackingService
{
    // VarPlayer 4526 = TRACKING_ORE_MINED
    // Increments once per ore mined, including bonus ores.
    // Multiple VarbitChanged events fire per tick when bonus ores occur.
    // Important, since inventory-tracking is useless if the player is using Infernal Pickaxe.
    // Since Infernal Pickaxe consumes the granite before it even enters inventory.
    private static final int TRACKING_ORE_MINED_VARP = 4526;

    // XP ranges per granite type (display values, not internal ×10).
    // OSRS tracks XP with one decimal internally. If an ore's true XP is fractional
    // (e.g. 75.5), StatChanged delivers either floor or ceil depending on accumulated
    // remainder — so two ores of the same type mined in the same tick can give
    // different display XP (e.g. 75+76=151 for 2x5kg).
    //
    // The +10 / +25 differences between ore types are constant across all modifiers.
    // Resolution uses a range check: distribution (a,b,c) is valid if
    //   MIN*a + (MIN+10)*b + (MIN+25)*c  <=  xp  <=  MAX*a + (MAX+10)*b + (MAX+25)*c
    //
    // Known ambiguities for ores=3 (returned as null / unresolved):
    //   xp in [175,176]: overlap between {2,0,1} and {1,2,0}
    //   xp in [185,186]: overlap between {1,1,1} and {0,3,0}
    // These require 2 bonus ores in one tick AND a specific XP value — negligibly rare.
    // As I'm not able to really figure out how to properly solve this, I'm leaving this bug as is.
    private static final int MIN_XP_500G = 50;
    private static final int MAX_XP_500G = 52;
    private static final int XP_DIFF_2KG = 10;
    private static final int XP_DIFF_5KG = 25;

    private static final String SWING_MESSAGE = "You swing your pick at the rock.";
    private static final String SUCCESS_PREFIX = "You manage to quarry some";

    private static final String VARROCK_ARMOR_MESSAGE = "The Varrock platebody enabled you to mine an additional ore.";
    private static final String CELESTIAL_RING_MESSAGE = "Your celestial ring glows and you manage to mine an extra ore.";
    private static final String MINING_CAPE_MESSAGE = "Your cape allows you to mine an additional ore.";

    private final Client client;

    // General statistics
    private int attempts = 0;
    private int successes = 0;

    // Bonus ore counts
    private int varrockArmorCount = 0;
    private int celestialRingCount = 0;
    private int miningCapeCount = 0;

    // Granite distribution
    private int count500g = 0;
    private int count2kg = 0;
    private int count5kg = 0;

    // Per-tick accumulation state
    private int lastMiningXp = -1;
    private int lastOreVarp = -1;
    private boolean oreBaselineInitialized = false;

    private int tickXpDelta = 0;
    private int tickOreDelta = 0;
    private boolean tickSuccess = false;

    @Inject
    public GraniteTrackingService(Client client)
    {
        this.client = client;
    }

    public void startUp()
    {
        reset();
    }

    public void shutDown()
    {
        attempts = 0;
        successes = 0;

        varrockArmorCount = 0;
        celestialRingCount = 0;
        miningCapeCount = 0;

        count500g = 0;
        count2kg = 0;
        count5kg = 0;

        lastMiningXp = -1;
        lastOreVarp = -1;
        oreBaselineInitialized = false;

        tickXpDelta = 0;
        tickOreDelta = 0;
        tickSuccess = false;
    }

    public void reset()
    {
        attempts = 0;
        successes = 0;

        varrockArmorCount = 0;
        celestialRingCount = 0;
        miningCapeCount = 0;

        count500g = 0;
        count2kg = 0;
        count5kg = 0;

        lastMiningXp = client.getSkillExperience(Skill.MINING);
        lastOreVarp = client.getVarpValue(TRACKING_ORE_MINED_VARP);
        oreBaselineInitialized = true;

        tickXpDelta = 0;
        tickOreDelta = 0;
        tickSuccess = false;
    }

    public void onChatMessage(ChatMessage event)
    {
        String message = event.getMessage();

        if (SWING_MESSAGE.equals(message))
        {
            attempts++;
            return;
        }

        if (message.startsWith(SUCCESS_PREFIX))
        {
            successes++;
            tickSuccess = true;
            return;
        }

        if (VARROCK_ARMOR_MESSAGE.equals(message))
        {
            varrockArmorCount++;
            return;
        }

        if (CELESTIAL_RING_MESSAGE.equals(message))
        {
            celestialRingCount++;
            return;
        }

        if (MINING_CAPE_MESSAGE.equals(message))
        {
            miningCapeCount++;
        }
    }

    public void onStatChanged(StatChanged event)
    {
        if (event.getSkill() != Skill.MINING)
        {
            return;
        }

        int currentXp = event.getXp();

        if (lastMiningXp != -1)
        {
            int delta = currentXp - lastMiningXp;

            if (delta > 0)
            {
                tickXpDelta += delta;
            }
        }

        lastMiningXp = currentXp;
    }

    public void onVarbitChanged(VarbitChanged event)
    {
        if (event.getVarpId() != TRACKING_ORE_MINED_VARP)
        {
            return;
        }

        int current = client.getVarpValue(TRACKING_ORE_MINED_VARP);

        if (!oreBaselineInitialized)
        {
            lastOreVarp = current;
            oreBaselineInitialized = true;
            return;
        }

        int delta = current - lastOreVarp;

        if (delta > 0)
        {
            tickOreDelta += delta;
        }

        lastOreVarp = current;
    }

    public void onGameTick(GameTick event)
    {
        // Only process if a success chat message was received this tick and at least
        // one ore was registered via the varp — both conditions must hold to avoid
        // counting spurious XP (e.g. from other mining activities).
        if (tickSuccess && tickOreDelta > 0)
        {
            processRoll(tickXpDelta, tickOreDelta);
        }

        // Always clear per-tick state so stale values never bleed into the next tick.
        tickXpDelta = 0;
        tickOreDelta = 0;
        tickSuccess = false;
    }

    private void processRoll(int xp, int ores)
    {
        int[] result = resolveGranite(xp, ores);

        if (result != null)
        {
            count500g += result[0];
            count2kg += result[1];
            count5kg += result[2];
        }

        if (result != null)
        {
            log.debug("Granite -> 500g: {} | 2kg: {} | 5kg: {}", result[0], result[1], result[2]);
        }
        else
        {
            log.debug("Granite resolution failed -> XP: {} | Ores: {}", xp, ores);
        }
    }

    /**
     * Resolves granite ore distribution from XP delta and ore count.
     *
     * Each ore type has an XP range due to fractional XP rounding in OSRS:
     *   500g: [MIN_XP_500G,          MAX_XP_500G         ]
     *   2kg:  [MIN_XP_500G+10,       MAX_XP_500G+10      ]
     *   5kg:  [MIN_XP_500G+25,       MAX_XP_500G+25      ]
     *
     * Distribution (a, b, c) is valid when the observed xp falls within the
     * achievable range for that distribution:
     *   minXp = MIN*a + (MIN+10)*b + (MIN+25)*c
     *   maxXp = MAX*a + (MAX+10)*b + (MAX+25)*c
     *
     * Returns null if zero or more than one distribution matches (ambiguous).
     *
     * @return int[3] = {count500g, count2kg, count5kg} or null if unresolvable
     */
    private int[] resolveGranite(int xp, int ores)
    {
        int[] solution = null;
        int solutionCount = 0;

        for (int c = ores; c >= 0; c--)
        {
            for (int b = ores - c; b >= 0; b--)
            {
                int a = ores - b - c;
                int minXp = MIN_XP_500G * a + (MIN_XP_500G + XP_DIFF_2KG) * b + (MIN_XP_500G + XP_DIFF_5KG) * c;
                int maxXp = MAX_XP_500G * a + (MAX_XP_500G + XP_DIFF_2KG) * b + (MAX_XP_500G + XP_DIFF_5KG) * c;

                if (xp >= minXp && xp <= maxXp)
                {
                    solution = new int[]{a, b, c};
                    solutionCount++;
                }
            }
        }

        return solutionCount == 1 ? solution : null;
    }

    /**
     * Loads saved statistics from a profile snapshot.
     * The XP and varp baselines are intentionally preserved so tracking continues
     * seamlessly from the current game state after the load.
     */
    public void loadFromProfile(ProfileData data)
    {
        attempts = data.attempts;
        successes = data.successes;
        varrockArmorCount = data.varrockArmorCount;
        celestialRingCount = data.celestialRingCount;
        miningCapeCount = data.miningCapeCount;
        count500g = data.count500g;
        count2kg = data.count2kg;
        count5kg = data.count5kg;

        // Reset tick accumulation — don't touch XP/varp baseline (keep tracking from now)
        tickXpDelta = 0;
        tickOreDelta = 0;
        tickSuccess = false;
    }

    // --- Getters: General statistics ---

    public int getAttempts()
    {
        return attempts;
    }

    public int getSuccesses()
    {
        return successes;
    }

    public int getFailures()
    {
        return Math.max(0, attempts - successes);
    }

    // --- Getters: Bonus ore counts ---

    public int getVarrockArmorCount()
    {
        return varrockArmorCount;
    }

    public int getCelestialRingCount()
    {
        return celestialRingCount;
    }

    public int getMiningCapeCount()
    {
        return miningCapeCount;
    }

    // --- Getters: Granite distribution ---

    public int getCount500g()
    {
        return count500g;
    }

    public int getCount2kg()
    {
        return count2kg;
    }

    public int getCount5kg()
    {
        return count5kg;
    }

    public int getTotalGraniteOres()
    {
        return count500g + count2kg + count5kg;
    }
}

package com.github.outlashed.granitetracker.overlays;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import javax.inject.Inject;
import com.github.outlashed.granitetracker.services.GraniteTrackingService;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;

public class GeneralStatisticsOverlay extends OverlayPanel
{
    private final GraniteTrackingService graniteTrackingService;

    @Inject
    public GeneralStatisticsOverlay(GraniteTrackingService graniteTrackingService)
    {
        this.graniteTrackingService = graniteTrackingService;
        setPosition(OverlayPosition.TOP_LEFT);
    }

    @Override
    public Dimension render(Graphics2D graphics)
    {
        panelComponent.getChildren().clear();

        panelComponent.getChildren().add(TitleComponent.builder()
                .text("General Statistics")
                .build());

        int attempts = graniteTrackingService.getAttempts();
        int successes = graniteTrackingService.getSuccesses();
        int failures = graniteTrackingService.getFailures();

        panelComponent.getChildren().add(LineComponent.builder()
                .left("Attempts")
                .right(String.valueOf(attempts))
                .build());

        panelComponent.getChildren().add(LineComponent.builder()
                .left("Successes")
                .right(formatWithPercent(successes, attempts))
                .rightColor(Color.GREEN)
                .build());

        panelComponent.getChildren().add(LineComponent.builder()
                .left("Failed")
                .right(formatWithPercent(failures, attempts))
                .rightColor(Color.RED)
                .build());

        panelComponent.getChildren().add(LineComponent.builder()
                .left("Varrock Armor")
                .right(formatWithPercent(graniteTrackingService.getVarrockArmorCount(), successes))
                .build());

        panelComponent.getChildren().add(LineComponent.builder()
                .left("Celestial Ring")
                .right(formatWithPercent(graniteTrackingService.getCelestialRingCount(), successes))
                .build());

        panelComponent.getChildren().add(LineComponent.builder()
                .left("Mining Cape")
                .right(formatWithPercent(graniteTrackingService.getMiningCapeCount(), successes))
                .build());

        return super.render(graphics);
    }

    private String formatWithPercent(int value, int total)
    {
        if (total == 0)
        {
            return String.valueOf(value);
        }

        double pct = (double) value / total * 100.0;
        return value + " (" + String.format("%.1f", pct) + "%)";
    }
}

